// Kobalte's parts hand theirs to `Dynamic`. Its contract (ADR 0207) states
// when the `on…` members of its props run: at an external event, when `as` is
// not a component. Everything else about its callbacks is left open.
export declare function Root(props: {
  as?: string | ((props: Record<string, unknown>) => JSX.Element);
  onClick?: (event: unknown) => void;
  onFocus?: (event: unknown) => void;
  render?: () => unknown;
  label?: string;
}): JSX.Element;
